// Bounded read-only source experiment: all writable state is new /tmp scratch.
import { mkdtempSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { applyDbSchema } from '/app/projects/may-agent/src/lib/db/schema.ts';
import { getDb, closeDb } from '/app/projects/may-agent/src/lib/requests.ts';
import { createMetricService } from '/app/projects/may-agent/src/lib/metrics.ts';
import { EventBus } from '/app/projects/may-agent/src/app/core/events/bus.ts';
import { measureSourceMetrics } from '/app/projects/may-agent/src/app/metric-source-measurement.ts';
const root = mkdtempSync(join(tmpdir(), 'bob-causal-probe-'));
process.env.APP_ROOT = root;
const db = getDb(root); applyDbSchema(db);
const service = createMetricService({getDb: () => db});
writeFileSync(join(root, 'producer.ts'), 'await Bun.sleep(200); console.log(JSON.stringify({value: 7, note: JSON.stringify({completedAt: Date.now()})}));\n');
service.define({id:'probe.causal', name:'Probe', type:'gauge', owner:'fixture', sourceCommand:`'${process.execPath}' producer.ts`});
const result = await measureSourceMetrics({bus:new EventBus(),persistDir:root});
// Fixture-only database, schema discovered before querying.
const schema = db.prepare('PRAGMA table_info(metric_snapshots)').all();
console.log(JSON.stringify({scratchRoot:root,schema}, null, 2));
const row = db.prepare('SELECT metric_id, measured_at, note FROM metric_snapshots WHERE metric_id = ? ORDER BY id DESC LIMIT 1').get('probe.causal') as any;
const completedAt = JSON.parse(row.note).completedAt;
console.log(JSON.stringify({result,row,completedAt,leadMs:completedAt-row.measured_at,observationPredatesCompletion:row.measured_at<completedAt},null,2));
closeDb(root);
if (!(row.measured_at<completedAt)) throw new Error('Expected current-source causality mismatch was not reproduced');

